import operator
from typing import Annotated, TypedDict
from langgraph.graph import StateGraph, START, END

class State(TypedDict):
    applicant_id: str
    findings: Annotated[list, operator.add]     # parallel branches append here

def credit(s):     return {"findings": [bureau_check(s["applicant_id"])]}
def statements(s): return {"findings": [analyze_statements(s["applicant_id"])]}
def employment(s): return {"findings": [verify_employer(s["applicant_id"])]}
def decide(s):     return {"findings": [underwrite(s["findings"])]}

g = StateGraph(State)
for name, fn in [("credit", credit), ("statements", statements),
                 ("employment", employment), ("decide", decide)]:
    g.add_node(name, fn)
for n in ("credit", "statements", "employment"):
    g.add_edge(START, n)                                        # fan out
g.add_edge(["credit", "statements", "employment"], "decide")   # join: waits for all
g.add_edge("decide", END)

app = g.compile()
app.invoke({"applicant_id": "A-1042", "findings": []})
